# PowerShell completion for kit-repo
# Generated by guanghechen-commander

Register-ArgumentCompleter -Native -CommandName 'kit-repo' -ScriptBlock {
  param($wordToComplete, $commandAst, $cursorPosition)
  $completed = @($commandAst.CommandElements | Where-Object { $_.Extent.EndOffset -lt $cursorPosition } | Select-Object -Skip 1 | ForEach-Object { if ($_ -is [System.Management.Automation.Language.StringConstantExpressionAst]) { $_.Value } else { $_.ToString() } })
  $records = & 'kit-repo' completion --pwsh -- @completed $wordToComplete
  foreach ($record in $records) {
    $fields = $record -split "`t", 2
    $candidate = $fields[0]
    $description = if ($fields.Count -gt 1) { $fields[1] } else { $candidate }
    $completionText = "'" + $candidate.Replace("'", "''") + "'"
    [System.Management.Automation.CompletionResult]::new($completionText, $candidate, 'ParameterValue', $description)
  }
}
